import { Accordion } from "@chakra-ui/react";
import type { ConversationEvent } from "../../types";
import { CommonEventInfo, DetailView, EventAccordionItem } from "./blocks";
import { BotLatencyAccordionItem } from "./LatencyDetails";

interface BotTurnEndedEventInfoProps {
  event: ConversationEvent;
  onClose: () => void;
}
export const BotTurnEndedEventInfo = ({ event, onClose }: BotTurnEndedEventInfoProps) => {
  return (
    <DetailView title="Agent turn ended" onClose={onClose}>
      <Accordion.Root collapsible multiple>
        <BotLatencyAccordionItem latencyBreakdown={event.metadata?.latency_breakdown} />
        <EventAccordionItem title="Event details" value="event-details">
          <CommonEventInfo event={event} />
        </EventAccordionItem>
      </Accordion.Root>
    </DetailView>
  );
};
